// Alertas de Zabbix a Telegram: clasifica en las 12 categorias pedidas y da formato. SOLO notifica (no reinicia nada).
// ===== CONFIGURACION =====
const ENVIAR_NO_RECONOCIDAS = true;   // true: una alerta que no encaja en ninguna categoria se envia como "OTRA ALERTA"
const hora = ms => new Date(ms - 6 * 3600 * 1000).toISOString().replace('T', ' ').slice(0, 19) + ' (CR)';

// ---------- 1. Datos recibidos ----------
const raw0 = $json.body !== undefined ? $json.body : $json;
let raw = raw0;
if (typeof raw0 === 'string') { try { raw = JSON.parse(raw0); } catch (_) { raw = { message: raw0 }; } }
if (!raw || typeof raw !== 'object') raw = { message: String(raw ?? '') };
// El campo "message" puede traer un JSON como texto: se abre y se mezcla.
if (typeof raw.message === 'string' && raw.message.trim().startsWith('{')) {
  try { const inner = JSON.parse(raw.message); if (inner && typeof inner === 'object') raw = { ...raw, ...inner, message: inner.message || '' }; } catch (_) {}
}
const get = (...keys) => { for (const k of keys) if (raw[k] !== undefined && raw[k] !== null && String(raw[k]).trim() !== '') return String(raw[k]).trim(); return ''; };
const subject = get('subject', 'Subject', 'title', 'name');
const message = get('message', 'Message', 'description');
const opdata = get('opdata', 'detail', 'detalle');
const plain = message.replace(/\\r\\n|\\r|\\n/g, '\n').replace(/\r/g, '\n');
// Mensajes en texto libre de Zabbix: "Host: X / Problema: Y / ..."
const campo = k => { const r = plain.match(new RegExp('(?:^|\\n)\\s*' + k + '\\s*:\\s*([^\\n]+)', 'i')); return r ? r[1].trim() : ''; };
const host = get('host', 'hostname', 'host_name') || campo('Host') || 'Host no identificado';
const trigger = get('trigger', 'trigger_name', 'event_name') || campo('Problema') || campo('Problem')
  || subject.replace(/^(PROBLEM|RECOVERY|RECOVERED|RESOLVED|OK|RECUPERADO|ALERTA[^:]*)\s*:\s*/i, '') || 'Evento Zabbix';
const severidad = get('severity', 'priority', 'severidad') || campo('Severidad');
const eventId = get('event_id', 'eventid');

// ---------- 2. Problema o recuperacion ----------
const st = get('status', 'event_status', 'event_value', 'value').toLowerCase();
const recuperado = ['ok', 'recovered', 'recovery', 'resolved', 'resuelto', 'recuperado', 'recuperada', '0'].includes(st)
  || /^(recovery|recovered|recuperad[oa]|resolved|resuelto|ok)\b/i.test(subject)
  || /estado\s*:\s*(recovery|recovered|ok|resolved)/i.test(plain);

// ---------- 3. Categoria (por el NOMBRE del trigger, no por el host) ----------
const T = (trigger + ' ' + subject).toLowerCase();
const H = host.toLowerCase();
const is = re => re.test(T);
const equipoRed = /mikrotik|rb\d{3,4}|sw-|switch|cisco|router|unifi|snmp/.test(H);
const so = /windows/.test(T + ' ' + H) ? ' WINDOWS' : (/ubuntu|linux|docker/.test(T + ' ' + H) ? ' UBUNTU' : '');
let categoria = null;
if (is(/\biis\b|w3svc|world wide web publishing/)) categoria = 'IIS CAIDO';
else if (is(/backup|respaldo|copia de seguridad|vzdump/)) categoria = 'BACKUPS (FALLO O ANTIGUEDAD)';
else if (is(/slow quer|slow_quer|slow sql|consultas? lent|quer(y|ies).*(lent|slow)|long.?running|queries lentos|latencia.{0,20}sql|sql.{0,20}(latenc|lent|slow)/)) categoria = 'QUERIES SQL LENTOS';
else if (is(/(disk|disco|device|block).*(latenc|await|respon|too high|queue|cola)|latencia.*disco|r_await|w_await|i\/o.*(wait|latenc)|request responses/)) categoria = 'LATENCIA DE DISCO';
else if (is(/respuesta lenta|tiempo de respuesta|response time|slow response|(crm|espocrm|http|web).*(lent|slow)/)) categoria = 'CRM CON RESPUESTA LENTA';
else if (is(/espocrm|crm/) && is(/no disponible|not available|unavailable|down|caid[oa]|fall/)) categoria = 'CAIDA DE ESPOCRM' + so;
else if (is(/mariadb|mysql|base de datos|database/) && is(/no disponible|not available|unavailable|down|caid[oa]|3306|fall/)) categoria = 'CAIDA DE MARIADB' + so;
else if (is(/\bcpu\b|processor|procesador|load average/)) categoria = 'CPU ALTA';
else if (is(/\bram\b|memory|memoria|swap/)) categoria = 'RAM ALTA';
else if (is(/disk space|filesystem|file system|espacio|storage|pused|vfs\.fs|space is (low|critic)|used >|% used/)) categoria = is(/critical|critic|> ?9\d|9\d ?%/) ? 'DISCO CRITICO' : 'DISCO ALTO';
else if (is(/link down|operational status|ifoperstatus|interface.*down|interfaz.*(ca[ií]d|down)|port.*down/)) categoria = 'CAIDA DE INTERFAZ';
else if (is(/bandwidth|ancho de banda|error rate|errors|errores|interface|interfaz/)) categoria = 'RED: ANCHO DE BANDA / ERRORES';
else if (is(/snmp/) || (equipoRed && is(/icmp|ping|unreachable|not available|unavailable|no disponible|down|caid/))) categoria = 'PERDIDA DE SNMP / EQUIPO DE RED';
else if (is(/proxmox|hypervisor|\bpve\b|qemu|vm .*(not running|stopped|offline|ca[ií]d)|maquina virtual|máquina virtual|zabbix agent.*(not available|unavailable)|agent.*no disponible|unavailable by icmp|icmp.*(loss|ping)|ping/)) categoria = 'PROXMOX / VM CAIDA';
const reconocida = categoria !== null;
if (!reconocida) categoria = 'OTRA ALERTA ZABBIX';

// ---------- 4. Hora del evento ----------
let evTime = get('event_time', 'time');
const evDate = get('event_date', 'date');
if (evDate && evTime && !/\d{4}/.test(evTime)) evTime = evDate + ' ' + evTime;
if (!evTime) {
  const h = plain.match(/(\d{2}:\d{2}:\d{2})/), f = plain.match(/(\d{4}[./-]\d{2}[./-]\d{2})/);
  if (h && f) evTime = f[1] + ' ' + h[1];
}

// ---------- 5. Mensaje ----------
const sev = severidad.toLowerCase();
const icono = recuperado ? '✅' : (/disaster|high|alta|critic|desastre/.test(sev) || /CRITICO|CAIDO|CAIDA/.test(categoria) ? '🔴' : (/average|media|warning|advertencia/.test(sev) ? '🟠' : '🚨'));
const detalle = (opdata || (plain && !/^\s*(estado|host)\s*:/i.test(plain) ? plain : '') || '').slice(0, 600);
const lineas = [
  icono + (recuperado ? ' ALERTA RECUPERADA' : ' NUEVA ALERTA') + ': ' + categoria,
  'Host: ' + host,
  'Trigger: ' + trigger,
  severidad ? 'Severidad: ' + severidad : null,
  'Hora del evento: ' + (evTime ? evTime.replace('{EVENT.DATE}', '').replace('{EVENT.TIME}', '').trim() + ' (Zabbix)' : 'n/d'),
  'Recibido en n8n: ' + hora(Date.now()),
  eventId ? 'Evento Zabbix: ' + eventId : null,
  detalle ? 'Detalle: ' + detalle : null
].filter(Boolean);
const limpiar = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const enviar = reconocida || ENVIAR_NO_RECONOCIDAS;
return { json: {
  enviar, categoria, estado: recuperado ? 'RECUPERADO' : 'PROBLEM', host, trigger, severidad, event_id: eventId,
  texto: lineas.map(limpiar).join('\n'),
  motivo_omitido: enviar ? '' : 'Evento no reconocido: revisar el nombre del trigger o el payload'
} };
